import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/technological-inventions/optics-and-information-technology/","title":"CH6.4 光学、传感与信息技术 | 英语","lang":"zh-CN","frontmatter":{"title":"CH6.4 光学、传感与信息技术","createTime":"2026-11-20T11:20:00.000Z","permalink":"/english/vocabulary/technological-inventions/optics-and-information-technology/"},"readingTime":{"minutes":30.53,"words":9160},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/technological-inventions/4.optics-and-information-technology.md","headers":[],"bulletin":false}`),a={name:`4.optics-and-information-technology.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="optics" tabindex="-1"><a class="header-anchor" href="#optics"><span>Optics</span></a></h2><p class="vc-meta"><strong>/ˈɒptɪks/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>光学（研究光与视觉的物理学分支）</li><li>（仪器、设备的）光学部件，镜片系统</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the optics of a lens</td><td>镜头的光学性能</td></tr><tr><td>fibre optics</td><td>光纤</td></tr><tr><td>precision optics</td><td>精密光学元件</td></tr><tr><td>optics research</td><td>光学研究</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how fibre optics carry signals along a glass thread.</p><blockquote><p>该示意图显示了光纤如何沿玻璃丝传递信号。</p></blockquote><p><strong>Writing Task 2</strong> Advances in optics made it possible to see cells that had been invisible for centuries.</p><blockquote><p>光学的进步让人们得以看见数百年来不可见的细胞。</p></blockquote><p><strong>Speaking</strong> The optics on this camera are better than the price suggests.</p><blockquote><p>这台相机的光学素质比价格看上去的好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>photonics</td><td>光子学</td><td>研究与操控光子，偏工程</td></tr><tr><td>lenses</td><td>镜片</td><td>具体部件，不是学科</td></tr><tr><td>optical</td><td>光学的</td><td>形容词，不能替代名词</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>optikos</em>（视觉的）← <em>ōps</em>（眼睛）</li><li><strong>Family:</strong> optics 光学 / optical 光学的 / optician 验光师 / optometrist 验光师（美式）</li><li><strong>Memory Tip:</strong> opt = 眼睛与看，同族有 optical、optician（配镜师）、autopsy（亲眼查看→尸检）。optics 作学科时视为单数。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作学科时用单数动词：Optics is a branch of physics。</li><li>拼写 op-tics，不是 <s>optis</s>。</li><li>别用 optics 代替形容词：<s>optics fibre</s> ✘ → optical fibre。</li></ul></div><div class="vocab-card"><h2 id="microscope" tabindex="-1"><a class="header-anchor" href="#microscope"><span>Microscope</span></a></h2><p class="vc-meta"><strong>/ˈmaɪkrəskəʊp/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>显微镜</li><li>（比喻）细致审视，放大检视</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>under the microscope</td><td>在显微镜下；受严密审视</td></tr><tr><td>an electron microscope</td><td>电子显微镜</td></tr><tr><td>a light microscope</td><td>光学显微镜</td></tr><tr><td>examine sth under a microscope</td><td>用显微镜观察</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows what a water sample looks like under a microscope.</p><blockquote><p>该示意图显示了水样在显微镜下的样子。</p></blockquote><p><strong>Writing Task 2</strong> Once a policy is placed under the microscope, its costs become impossible to hide.</p><blockquote><p>一旦政策被放在放大镜下审视，其成本就无处躲藏。</p></blockquote><p><strong>Speaking</strong> We looked at onion cells under the microscope in biology.</p><blockquote><p>生物课上我们用显微镜看洋葱细胞。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>magnifier</td><td>放大镜</td><td>倍数低，结构简单</td></tr><tr><td>magnifying glass</td><td>放大镜</td><td>日常用语</td></tr><tr><td>scope</td><td>镜；范围</td><td>口语缩略，也指&quot;余地&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>micro-</em>（微小）+ 希腊 <em>skopein</em>（看）</li><li><strong>Family:</strong> microscope 显微镜 / microscopic 微观的 / microbe 微生物 / telescope 望远镜</li><li><strong>Memory Tip:</strong> scope 是&quot;看&quot;：microscope 看小的，telescope 看远的，kaleidoscope 看美的（万花筒）。一串词一个词根就串起来了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 under：under the microscope。</li><li>microscopic 是&quot;极小的、微观的&quot;，不是&quot;显微镜的&quot;。</li><li>拼写 micro-scope 连写，不是 <s>micro scope</s>。</li></ul></div><div class="vocab-card"><h2 id="lens" tabindex="-1"><a class="header-anchor" href="#lens"><span>Lens</span></a></h2><p class="vc-meta"><strong>/lenz/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>透镜，镜片；镜头</li><li>（眼睛的）晶状体；（比喻）视角</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a camera lens</td><td>相机镜头</td></tr><tr><td>a contact lens</td><td>隐形眼镜</td></tr><tr><td>through the lens of</td><td>从……的视角</td></tr><tr><td>a wide-angle lens</td><td>广角镜头</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows light passing through a convex lens and meeting at a point.</p><blockquote><p>该示意图显示了光通过凸透镜并在一点汇聚。</p></blockquote><p><strong>Writing Task 2</strong> History is usually written through the lens of those who won.</p><blockquote><p>历史通常是从胜利者的视角书写的。</p></blockquote><p><strong>Speaking</strong> I scratched the lens on my sunglasses and now everything looks blurry.</p><blockquote><p>我把墨镜镜片刮花了，现在看什么都模糊。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>glass</td><td>镜片</td><td>口语指眼镜片，也可指玻璃</td></tr><tr><td>optic</td><td>光学元件</td><td>技术用语，少单独用</td></tr><tr><td>viewpoint</td><td>视角</td><td>只用于比喻义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>lens</em>（小扁豆）——因凸透镜形似扁豆</li><li><strong>Family:</strong> lens 透镜 / lenses 复数 / lentil 小扁豆（同源）/ lensman 摄影师（旧称）</li><li><strong>Memory Tip:</strong> 词源就是&quot;扁豆&quot;：凸透镜的形状像颗扁豆，于是借来做名字。复数 lenses，读 /ˈlenzɪz/。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 lenses，不是 <s>lenss</s>。</li><li>比喻义 through the lens of 是高频写作搭配，介词不用 <s>by</s>。</li><li>眼睛的&quot;晶状体&quot;也是 lens，医学语境不加 a 表整体时注意。</li></ul></div><div class="vocab-card"><h2 id="radar" tabindex="-1"><a class="header-anchor" href="#radar"><span>Radar</span></a></h2><p class="vc-meta"><strong>/ˈreɪdɑː(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>雷达（无线电探测与测距）</li><li>（比喻）警觉，注意（on the radar）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>radar detection</td><td>雷达探测</td></tr><tr><td>on the radar</td><td>受到关注，在考虑范围内</td></tr><tr><td>below the radar</td><td>未被注意</td></tr><tr><td>radar system</td><td>雷达系统</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the area covered by the airport&#39;s radar.</p><blockquote><p>该地图显示了机场雷达覆盖的区域。</p></blockquote><p><strong>Writing Task 2</strong> Species that fall below the radar receive almost no conservation funding.</p><blockquote><p>未受关注的物种几乎得不到保护经费。</p></blockquote><p><strong>Speaking</strong> The flight was delayed because of a radar fault.</p><blockquote><p>航班因雷达故障延误。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sonar</td><td>声呐</td><td>用声波，水下探测</td></tr><tr><td>lidar</td><td>激光雷达</td><td>用激光，测绘与自动驾驶</td></tr><tr><td>detection system</td><td>探测系统</td><td>泛指，非专有技术</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 缩略词 <em>RA</em>dio <em>D</em>etection <em>A</em>nd <em>R</em>anging（无线电探测与测距）</li><li><strong>Family:</strong> radar 雷达 / sonar 声呐 / lidar 激光雷达</li><li><strong>Memory Tip:</strong> 这类词都是首字母拼成的新词（acronym）：radar、sonar、lidar。记住全称就记住了原理：用无线电/声波/激光去&quot;测距&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>首字母缩略但已普通化，一般小写 radar。</li><li>on the radar 是&quot;受关注&quot;，below the radar 是&quot;未被注意&quot;，别弄反。</li><li>不用复数表多套系统时加 -s 亦可，但通常作不可数。</li></ul></div><div class="vocab-card"><h2 id="echo" tabindex="-1"><a class="header-anchor" href="#echo"><span>Echo</span></a></h2><p class="vc-meta"><strong>/ˈekəʊ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：回声，回响；附和，共鸣</li><li>动词：发出回声；重复（他人观点）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>echo across</td><td>在……回荡</td></tr><tr><td>echo sb&#39;s view</td><td>附和某人的观点</td></tr><tr><td>a faint echo</td><td>微弱的回声</td></tr><tr><td>echo sounder</td><td>回声探测仪</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how an echo sounder measures the depth of the seabed.</p><blockquote><p>该示意图显示了回声探测仪如何测量海床深度。</p></blockquote><p><strong>Writing Task 2</strong> The minister&#39;s speech echoed arguments made by the industry a decade earlier.</p><blockquote><p>部长的讲话重复了该行业十年前的观点。</p></blockquote><p><strong>Speaking</strong> Our voices echoed around the empty hall.</p><blockquote><p>我们的声音在空荡的大厅里回响。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>reverberation</td><td>混响</td><td>声学术语，指持续反射</td></tr><tr><td>resonance</td><td>共鸣</td><td>多用于比喻与物理</td></tr><tr><td>repeat</td><td>重复</td><td>中性，不含&quot;呼应&quot;意象</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>ēkhō</em>（声音），神话中为山林女神 Echo</li><li><strong>Family:</strong> echo 回声 / echoic 拟声的 / echo chamber 回音室；信息茧房</li><li><strong>Memory Tip:</strong> 希腊神话里 Echo 只能重复别人最后几个字，于是她的名字成了&quot;回声&quot;。echo chamber 现在常指&quot;只听得见同类观点的圈子&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 echoes，不是 <s>echos</s>。</li><li>动词&quot;附和&quot;带宾语：echo sb&#39;s concerns。</li><li>拼写 e-c-h-o，注意 -ch- 读 /k/。</li></ul></div><div class="vocab-card"><h2 id="sensor" tabindex="-1"><a class="header-anchor" href="#sensor"><span>Sensor</span></a></h2><p class="vc-meta"><strong>/ˈsensə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>传感器，感应器（把物理量转成信号）</li><li>探测装置</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a temperature sensor</td><td>温度传感器</td></tr><tr><td>a motion sensor</td><td>移动感应器</td></tr><tr><td>sensor data</td><td>传感器数据</td></tr><tr><td>be fitted with sensors</td><td>装有传感器</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how sensors on the roof record light levels.</p><blockquote><p>该示意图显示了屋顶上的传感器如何记录光照水平。</p></blockquote><p><strong>Writing Task 2</strong> Cheap sensors have made air quality something citizens can measure themselves.</p><blockquote><p>廉价的传感器让空气质量成了市民自己就能测的东西。</p></blockquote><p><strong>Speaking</strong> The light has a motion sensor, so it turns on when you walk in.</p><blockquote><p>这灯有移动感应器，走进去就亮。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>detector</td><td>探测器</td><td>侧重&quot;发现是否存在&quot;</td></tr><tr><td>probe</td><td>探头</td><td>多指插入式测量头</td></tr><tr><td>gauge</td><td>仪表</td><td>需人读数，非自动输出信号</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>sentire</em>（感觉）→ <em>sensus</em></li><li><strong>Family:</strong> sensor 传感器 / sense 感觉 / sensitive 敏感的 / sensation 感觉；轰动</li><li><strong>Memory Tip:</strong> sens = 感觉，传感器就是&quot;给机器装上感官&quot;。同族 sense、sensitive、consensus（共同感觉→共识）都好记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 sen-sor，别写成 <s>censor</s>（那是&quot;审查&quot;）。</li><li>可数：a sensor / sensors。</li><li>说&quot;装有传感器&quot;用 be fitted with sensors，不用 <s>be installed sensors</s>。</li></ul></div><div class="vocab-card"><h2 id="multimedia" tabindex="-1"><a class="header-anchor" href="#multimedia"><span>Multimedia</span></a></h2><p class="vc-meta"><strong>/ˌmʌltiˈmiːdiə/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>多媒体（文字、图像、声音、视频的组合）</li><li>形容词：多媒体的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>multimedia technology</td><td>多媒体技术</td></tr><tr><td>a multimedia presentation</td><td>多媒体演示</td></tr><tr><td>multimedia content</td><td>多媒体内容</td></tr><tr><td>multimedia classroom</td><td>多媒体教室</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how the multimedia system links sound, image and text.</p><blockquote><p>该示意图显示了多媒体系统如何把声音、图像与文字连接起来。</p></blockquote><p><strong>Writing Task 2</strong> Multimedia lessons hold attention but do not always improve understanding.</p><blockquote><p>多媒体课程更能抓住注意力，却未必总能提升理解。</p></blockquote><p><strong>Speaking</strong> The museum uses multimedia to explain how the engine works.</p><blockquote><p>博物馆用多媒体讲解发动机的原理。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>audio-visual</td><td>视听的</td><td>只涵盖声音与画面</td></tr><tr><td>interactive media</td><td>互动媒体</td><td>强调交互性</td></tr><tr><td>digital media</td><td>数字媒体</td><td>强调数字化形态</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>multi-</em>（多）+ <em>media</em>（媒介，medium 的复数）</li><li><strong>Family:</strong> multimedia 多媒体 / medium 媒介 / media 媒体 / multimedia 作定语不加 -s</li><li><strong>Memory Tip:</strong> medium 的复数是 media（不是 <s>mediums</s>，指&quot;灵媒&quot;时才用）。multi- 家族还有 multilingual（多语的）、multicultural（多元文化的）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作定语时不加 -s：<s>multimedias</s> ✘。</li><li>拼写 multi-media 常连写，英式也可带连字符。</li><li>media 本身已是复数，<s>medias</s> ✘。</li></ul></div><div class="vocab-card"><h2 id="network" tabindex="-1"><a class="header-anchor" href="#network"><span>Network</span></a></h2><p class="vc-meta"><strong>/ˈnetwɜːk/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>网络（计算机、交通、人际）</li><li>动词：建立人脉；联网</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a computer network</td><td>计算机网络</td></tr><tr><td>the rail network</td><td>铁路网</td></tr><tr><td>a network of</td><td>一张……的网络</td></tr><tr><td>build a network</td><td>建立人脉</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the new line connects to the existing rail network.</p><blockquote><p>该地图显示了新线路如何接入现有铁路网。</p></blockquote><p><strong>Writing Task 2</strong> Weak social networks matter more in a crisis than strong ones.</p><blockquote><p>危机中，弱关系网络比强关系更有用。</p></blockquote><p><strong>Speaking</strong> I networked like mad at the conference and got two interviews.</p><blockquote><p>我在会上拼命攒人脉，拿到两个面试。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>grid</td><td>网架；电网</td><td>多指规则的网格系统</td></tr><tr><td>web</td><td>网；网络</td><td>强调交织，也指万维网</td></tr><tr><td>system</td><td>系统</td><td>泛指，不含&quot;互联&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>net</em>（网）+ <em>work</em>（结构、运作）</li><li><strong>Family:</strong> network 网络 / networking 人脉经营；组网 / networked 联网的 / net 网</li><li><strong>Memory Tip:</strong> net + work 直译就是&quot;网状结构&quot;。networking 在现代英语里既指&quot;建人脉&quot;，也指&quot;计算机组网&quot;，看语境分辨。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a network / networks。</li><li>&quot;建立人脉&quot;动词用 network，不加宾语：<s>network people</s> ✘。</li><li>拼写 net-work 连写，不分开写。</li></ul></div><div class="vocab-card"><h2 id="browser" tabindex="-1"><a class="header-anchor" href="#browser"><span>Browser</span></a></h2><p class="vc-meta"><strong>/ˈbraʊzə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>浏览器</li><li>浏览者，随便翻看的人</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a web browser</td><td>网页浏览器</td></tr><tr><td>browser history</td><td>浏览记录</td></tr><tr><td>open in a browser</td><td>在浏览器中打开</td></tr><tr><td>browser window</td><td>浏览器窗口</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows which browser users chose most often in 2025.</p><blockquote><p>该图表显示了 2025 年用户最常选择的浏览器。</p></blockquote><p><strong>Writing Task 2</strong> A browser decides what you never see as much as what you do.</p><blockquote><p>浏览器既决定你看到什么，也决定你永远看不到什么。</p></blockquote><p><strong>Speaking</strong> Try opening it in another browser — that usually fixes it.</p><blockquote><p>换个浏览器打开试试，通常就好了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>reader</td><td>阅读器</td><td>用于电子书格式</td></tr><tr><td>client</td><td>客户端</td><td>技术术语，泛指终端程序</td></tr><tr><td>search engine</td><td>搜索引擎</td><td>功能不同，别混用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>browse</em>（翻看、啃食嫩叶）+ <em>-er</em></li><li><strong>Family:</strong> browser 浏览器 / browse 浏览 / browsing 浏览 / browser-based 基于浏览器的</li><li><strong>Memory Tip:</strong> browse 原指鹿&quot;啃嫩枝叶&quot;，引申为&quot;随手翻看&quot;——像在书架上东翻西翻。浏览器就是帮你翻网页的那层东西。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>浏览器是 browser，搜索引擎是 search engine，中文常混。</li><li>可数：a browser / two browsers。</li><li>拼写 brow-ser，注意 ou。</li></ul></div><div class="vocab-card"><h2 id="dial" tabindex="-1"><a class="header-anchor" href="#dial"><span>Dial</span></a></h2><p class="vc-meta"><strong>/ˈdaɪəl/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：表盘，刻度盘；（旧式电话的）拨号盘</li><li>动词：拨（号码）；调节（旋钮）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>dial a number</td><td>拨号码</td></tr><tr><td>the dial of a gauge</td><td>仪表的刻度盘</td></tr><tr><td>speed dial</td><td>快速拨号</td></tr><tr><td>dial up</td><td>调高；拨号上网</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the dial of the meter and the scale marked on it.</p><blockquote><p>该示意图显示了仪表的刻度盘及其上标注的刻度。</p></blockquote><p><strong>Writing Task 2</strong> Few people under thirty have ever dialled a rotary phone.</p><blockquote><p>三十岁以下的人很少拨过转盘电话。</p></blockquote><p><strong>Speaking</strong> Just dial the extension and ask for Mei.</p><blockquote><p>拨分机号找梅就行。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>face</td><td>表盘</td><td>钟表术语，a clock face</td></tr><tr><td>knob</td><td>旋钮</td><td>指可转动的把手</td></tr><tr><td>ring</td><td>打电话</td><td>口语，英式常用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>dies</em>（日）→ <em>dialis</em>（每日的）→ 日晷、表盘</li><li><strong>Family:</strong> dial 表盘；拨号 / diary 日记（同源&quot;每日&quot;）/ daily 每日的</li><li><strong>Memory Tip:</strong> dial 与 diary、daily 同源，都是&quot;日&quot;——日晷上有刻度，后来刻度盘都叫 dial。所以表盘和拨号盘是同一个词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词过去式英式常双写：dialled / dialling，美式 dialed / dialing。</li><li>&quot;拨电话&quot;是 dial a number，不是 <s>dial to a number</s>。</li><li>名词&quot;表盘&quot;可数：a dial with two pointers。</li></ul></div><div class="vocab-card"><h2 id="microcomputer" tabindex="-1"><a class="header-anchor" href="#microcomputer"><span>Microcomputer</span></a></h2><p class="vc-meta"><strong>/ˌmaɪkrəʊkəmˈpjuːtə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>微型计算机（以微处理器为核心的计算机）</li><li>个人电脑（旧称）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a microcomputer system</td><td>微型计算机系统</td></tr><tr><td>early microcomputers</td><td>早期微型计算机</td></tr><tr><td>microcomputer chip</td><td>微机芯片</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how microcomputer sales overtook mainframes in the 1980s.</p><blockquote><p>该图表显示了 20 世纪 80 年代微机销量如何超过大型机。</p></blockquote><p><strong>Writing Task 2</strong> The microcomputer moved computing from institutions into homes.</p><blockquote><p>微型计算机把计算能力从机构带进了家庭。</p></blockquote><p><strong>Speaking</strong> My father still keeps his first microcomputer in the loft.</p><blockquote><p>我爸还把他第一台微机放在阁楼里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>personal computer</td><td>个人电脑</td><td>强调使用者，非技术规格</td></tr><tr><td>PC</td><td>个人电脑</td><td>缩写，口语常用</td></tr><tr><td>workstation</td><td>工作站</td><td>性能更高，专业用途</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>micro-</em>（微小）+ <em>computer</em>（计算机）</li><li><strong>Family:</strong> microcomputer 微机 / microprocessor 微处理器 / microchip 微芯片 / mainframe 大型机</li><li><strong>Memory Tip:</strong> micro- 家族可按尺度排：microchip（芯片）→ microcomputer（微机）→ mainframe（大型机）。写作里描述技术演进时这组词很有用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>现代口语几乎不说 microcomputer，用 PC 或 laptop。</li><li>拼写 micro-computer 连写，重音在 -pu-。</li><li>别与 microprocessor（微处理器，芯片）混。</li></ul></div><div class="vocab-card"><h2 id="laptop" tabindex="-1"><a class="header-anchor" href="#laptop"><span>Laptop</span></a></h2><p class="vc-meta"><strong>/ˈlæptɒp/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>笔记本电脑（可放在膝上使用）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a laptop computer</td><td>笔记本电脑</td></tr><tr><td>on a laptop</td><td>在笔记本电脑上</td></tr><tr><td>laptop battery</td><td>笔记本电池</td></tr><tr><td>a lightweight laptop</td><td>轻便笔记本</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows laptop ownership rising sharply after 2010.</p><blockquote><p>该图表显示 2010 年后笔记本电脑的拥有率急剧上升。</p></blockquote><p><strong>Writing Task 2</strong> Giving every pupil a laptop does less for learning than training teachers well.</p><blockquote><p>给每个学生配一台笔记本，对学习的帮助不及把教师培训好。</p></blockquote><p><strong>Speaking</strong> I do all my writing on a laptop, never on paper.</p><blockquote><p>我所有东西都在笔记本上写，从不用纸。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>notebook</td><td>笔记本（电脑）</td><td>英式常用，也可指纸质本</td></tr><tr><td>portable computer</td><td>便携电脑</td><td>正式，涵盖范围更广</td></tr><tr><td>desktop</td><td>台式机</td><td>反面参照词</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>lap</em>（大腿）+ <em>top</em>（上面）</li><li><strong>Family:</strong> laptop 笔记本 / desktop 台式机 / palmtop 掌上电脑（旧）/ tablet 平板</li><li><strong>Memory Tip:</strong> 按&quot;放在哪里&quot;命名的一串：laptop（膝上）、desktop（桌上）、palmtop（掌上）。这套构词法一眼就懂。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 lap-top 连写，不是 <s>lap top</s>。</li><li>说&quot;在电脑上&quot;用 on a laptop，不用 <s>in</s>。</li><li>英式也常用 notebook，但易与纸质笔记本混，正式写作说 laptop computer。</li></ul></div><div class="vocab-card"><h2 id="software" tabindex="-1"><a class="header-anchor" href="#software"><span>Software</span></a></h2><p class="vc-meta"><strong>/ˈsɒftweə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>软件（程序与相关数据，不可数）</li><li>（比喻）方法、流程等&quot;软&quot;的部分</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a piece of software</td><td>一款软件</td></tr><tr><td>software development</td><td>软件开发</td></tr><tr><td>install software</td><td>安装软件</td></tr><tr><td>software engineer</td><td>软件工程师</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how the software processes data from the sensors.</p><blockquote><p>该示意图显示了软件如何处理来自传感器的数据。</p></blockquote><p><strong>Writing Task 2</strong> Better software cannot fix a process that nobody has thought through.</p><blockquote><p>再好的软件也修不好一个没人想清楚的流程。</p></blockquote><p><strong>Speaking</strong> The software keeps crashing when I open two files at once.</p><blockquote><p>我一开两个文件软件就崩。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>program</td><td>程序</td><td>可数，指单个程序</td></tr><tr><td>application</td><td>应用程序</td><td>可数，指具体应用</td></tr><tr><td>platform</td><td>平台</td><td>指运行环境，非软件本身</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>soft</em>（软）+ <em>ware</em>（制品），20 世纪 50 年代仿 hardware 造出</li><li><strong>Family:</strong> software 软件 / hardware 硬件 / firmware 固件 / ware 制品</li><li><strong>Memory Tip:</strong> hardware 原指&quot;五金器具&quot;，计算机时代借来指硬件；相对的 software 就是&quot;软的家伙&quot;。ware 表示&quot;制品&quot;：silverware、kitchenware。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>a software</s> ✘，说 a piece of software 或 an application。</li><li>拼写 soft-ware 连写，不分开。</li><li>别与 hardware 混：hardware 指实体设备。</li></ul></div><div class="vocab-card"><h2 id="keyboard" tabindex="-1"><a class="header-anchor" href="#keyboard"><span>Keyboard</span></a></h2><p class="vc-meta"><strong>/ˈkiːbɔːd/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>键盘（电脑、打字机）</li><li>（乐器的）键盘</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a computer keyboard</td><td>电脑键盘</td></tr><tr><td>on-screen keyboard</td><td>屏幕键盘</td></tr><tr><td>keyboard shortcut</td><td>键盘快捷键</td></tr><tr><td>a wireless keyboard</td><td>无线键盘</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the layout of the keyboard on the control panel.</p><blockquote><p>该示意图显示了控制面板上键盘的布局。</p></blockquote><p><strong>Writing Task 2</strong> Children who type before they write may never learn proper handwriting.</p><blockquote><p>先学打字后学写字的孩子可能永远学不好书写。</p></blockquote><p><strong>Speaking</strong> My keyboard is sticky — I spilled tea on it last week.</p><blockquote><p>我键盘黏黏的，上周洒了茶。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>keypad</td><td>小键盘</td><td>数字键区，如 ATM</td></tr><tr><td>console</td><td>控制台</td><td>含屏幕与按键的整机</td></tr><tr><td>keys</td><td>按键</td><td>指单个键，不指整体</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>key</em>（键）+ <em>board</em>（板）</li><li><strong>Family:</strong> keyboard 键盘 / key 键；关键 / keypad 小键盘 / keylogger 键盘记录器</li><li><strong>Memory Tip:</strong> board 表&quot;板&quot;：keyboard（键盘）、blackboard（黑板）、dashboard（仪表板）。一眼就能看出这是一块排满键的板。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a keyboard / keyboards。</li><li>拼写 key-board 连写，不分开。</li><li>&quot;在键盘上打字&quot;用 on the keyboard，不用 <s>in</s>。</li></ul></div><div class="vocab-card"><h2 id="screen" tabindex="-1"><a class="header-anchor" href="#screen"><span>Screen</span></a></h2><p class="vc-meta"><strong>/skriːn/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：屏幕，显示屏；屏风，隔板</li><li>动词：筛查，审查；放映；遮挡</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>on screen</td><td>在屏幕上</td></tr><tr><td>screen time</td><td>屏幕使用时间</td></tr><tr><td>screen patients for</td><td>对病人进行……筛查</td></tr><tr><td>a touch screen</td><td>触摸屏</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares average daily screen time across age groups.</p><blockquote><p>该图表比较了各年龄段的日均屏幕使用时间。</p></blockquote><p><strong>Writing Task 2</strong> Screening every passenger would slow airports to a halt.</p><blockquote><p>对每位乘客都做筛查会让机场陷入瘫痪。</p></blockquote><p><strong>Speaking</strong> I&#39;ve been staring at a screen all day and my eyes hurt.</p><blockquote><p>我盯着屏幕一整天，眼睛疼。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>display</td><td>显示屏</td><td>技术用语，指显示器件</td></tr><tr><td>monitor</td><td>显示器</td><td>指独立的外接屏幕</td></tr><tr><td>filter</td><td>筛选</td><td>与 screen 的&quot;筛查&quot;义接近</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>escren</em>（挡火的屏）</li><li><strong>Family:</strong> screen 屏幕；筛查 / screening 筛查；放映 / sunscreen 防晒霜</li><li><strong>Memory Tip:</strong> 本义是&quot;挡在火前的屏风&quot;——既挡视线也挡热。于是&quot;屏幕&quot;和&quot;筛查（挡掉不合格的）&quot;两层意思都从&quot;挡&quot;来。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;在屏幕上&quot;用 on screen 或 on the screen，不用 <s>in</s>。</li><li>动词&quot;筛查&quot;是及物：screen blood donations。</li><li>可数：a screen / two screens。</li></ul></div><div class="vocab-card"><h2 id="loudspeaker" tabindex="-1"><a class="header-anchor" href="#loudspeaker"><span>Loudspeaker</span></a></h2><p class="vc-meta"><strong>/ˌlaʊdˈspiːkə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>扬声器，喇叭</li><li>（比喻）代言人，传声筒</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>over the loudspeaker</td><td>通过扬声器</td></tr><tr><td>a public address loudspeaker</td><td>广播喇叭</td></tr><tr><td>built-in loudspeaker</td><td>内置扬声器</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows where the loudspeakers are mounted in the hall.</p><blockquote><p>该示意图显示了扬声器在大厅中的安装位置。</p></blockquote><p><strong>Writing Task 2</strong> Social media turned every user into a loudspeaker for opinions nobody checked.</p><blockquote><p>社交媒体把每个用户都变成了未经核实的观点的扩音器。</p></blockquote><p><strong>Speaking</strong> The announcement came over the loudspeaker just as we sat down.</p><blockquote><p>我们刚坐下，广播就响了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>speaker</td><td>扬声器</td><td>口语缩略，最常用</td></tr><tr><td>amplifier</td><td>功放</td><td>放大信号的设备，非发声单元</td></tr><tr><td>PA system</td><td>广播系统</td><td>指整套公共广播设备</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>loud</em>（响亮）+ <em>speaker</em>（说话者）</li><li><strong>Family:</strong> loudspeaker 扬声器 / speaker 扬声器；演讲者 / loud 大声的 / aloud 出声地</li><li><strong>Memory Tip:</strong> 一词两义：speaker 既指&quot;说话的人&quot;，也指&quot;替人发声的器件&quot;。loud 只是修饰&quot;声音大&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>日常口语说 speaker 就够，loudspeaker 偏正式。</li><li>拼写 loud-speaker 连写，不分开。</li><li>与 microphone 方向相反：一个出声，一个收音。</li></ul></div><div class="vocab-card"><h2 id="microphone" tabindex="-1"><a class="header-anchor" href="#microphone"><span>Microphone</span></a></h2><p class="vc-meta"><strong>/ˈmaɪkrəfəʊn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>麦克风，话筒（把声音转为电信号）</li><li>（比喻）传声筒，代言渠道</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>speak into a microphone</td><td>对着话筒说话</td></tr><tr><td>a wireless microphone</td><td>无线麦克风</td></tr><tr><td>microphone stand</td><td>话筒架</td></tr><tr><td>turn on the microphone</td><td>打开话筒</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the microphone picking up sound and sending it to the recorder.</p><blockquote><p>该示意图显示了麦克风拾取声音并送至录音机。</p></blockquote><p><strong>Writing Task 2</strong> Giving everyone a microphone does not produce a debate; it produces noise.</p><blockquote><p>给每个人一只话筒并不产生辩论，只产生噪音。</p></blockquote><p><strong>Speaking</strong> Could you speak into the microphone? We can&#39;t hear you at the back.</p><blockquote><p>能对着话筒说吗？后面听不见。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mic</td><td>麦克风</td><td>口语缩略，最常用</td></tr><tr><td>mike</td><td>麦克风</td><td>旧式拼法，仍见于口语</td></tr><tr><td>pickup</td><td>拾音器</td><td>技术用语，指拾音部件</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>micro-</em>（微小）+ 希腊 <em>phōnē</em>（声音）</li><li><strong>Family:</strong> microphone 麦克风 / phone 电话 / telephone 电话 / phonetics 语音学 / megaphone 扩音器</li><li><strong>Memory Tip:</strong> phon = 声音，一串词：telephone（远声）、megaphone（大声）、saxophone（萨克斯&quot;声音&quot;）。micro- 表示它拾取&quot;微弱&quot;的声音。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 micro-phone 连写，重音在第一音节 /ˈmaɪkrəfəʊn/。</li><li>介词用 into：speak into a microphone。</li><li>口语缩写 mic 读 /maɪk/，写作里正式场合写全称。</li></ul></div><div class="vocab-card"><h2 id="cassette" tabindex="-1"><a class="header-anchor" href="#cassette"><span>Cassette</span></a></h2><p class="vc-meta"><strong>/kəˈset/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>盒式磁带；暗盒，胶卷盒</li><li>（设备的）插匣，卡式组件</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a cassette tape</td><td>盒式磁带</td></tr><tr><td>a cassette player</td><td>磁带播放机</td></tr><tr><td>cassette recorder</td><td>盒式录音机</td></tr><tr><td>on cassette</td><td>以磁带形式</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows music sales shifting from cassette to download within a decade.</p><blockquote><p>该图表显示音乐销量在十年内从磁带转向下载。</p></blockquote><p><strong>Writing Task 2</strong> Obsolete formats such as cassettes survive because some listeners prefer their imperfections.</p><blockquote><p>磁带这类过时格式仍有生命力，因为有些听众偏爱它的不完美。</p></blockquote><p><strong>Speaking</strong> My mum still has a box of cassettes in the car.</p><blockquote><p>我妈车里还有一盒磁带。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tape</td><td>磁带</td><td>泛指，也指胶带</td></tr><tr><td>cartridge</td><td>卡盒</td><td>多用于打印机、游戏机</td></tr><tr><td>disk</td><td>磁盘</td><td>介质不同，不是磁带</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>cassette</em> ← 意大利语 <em>cassetta</em>（小盒子）← <em>cassa</em>（箱子）</li><li><strong>Family:</strong> cassette 磁带盒 / case 箱子；情况 / cash 现金（同源&quot;钱箱&quot;）</li><li><strong>Memory Tip:</strong> 词源是&quot;小盒子&quot;，所以磁带、胶卷、打印机的&quot;卡盒&quot;都叫 cassette——本质都是个装东西的小盒。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>重音在第二音节 /kəˈset/，不是第一音节。</li><li>拼写双 s 双 t：cas-sette。</li><li>现在多用于历史叙述，说&quot;磁带&quot;日常用 tape 更自然。</li></ul></div><div class="vocab-card"><h2 id="tape" tabindex="-1"><a class="header-anchor" href="#tape"><span>Tape</span></a></h2><p class="vc-meta"><strong>/teɪp/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：磁带，录音带；胶带，带子</li><li>动词：录制；用胶带粘贴</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>magnetic tape</td><td>磁带</td></tr><tr><td>sticky tape</td><td>胶带</td></tr><tr><td>tape a programme</td><td>录节目</td></tr><tr><td>tape sth to sth</td><td>把某物贴到某物上</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how data was stored on magnetic tape before disks existed.</p><blockquote><p>该示意图显示了磁盘出现之前数据如何存储在磁带上。</p></blockquote><p><strong>Writing Task 2</strong> Taping a lecture saves the words but loses the thinking that produced them.</p><blockquote><p>录下讲座留住了字句，却丢掉了产生这些字句的思考。</p></blockquote><p><strong>Speaking</strong> I taped the note to the fridge so I wouldn&#39;t forget.</p><blockquote><p>我把便条贴在冰箱上，免得忘。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cassette</td><td>盒式磁带</td><td>指带盒，不是带子本身</td></tr><tr><td>recording</td><td>录音</td><td>指成品，不是介质</td></tr><tr><td>strip</td><td>条，带</td><td>泛指细长条状物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>tæppe</em>（窄条、带子）</li><li><strong>Family:</strong> tape 带子；录制 / tape recorder 录音机 / red tape 繁文缛节 / tapeworm 绦虫</li><li><strong>Memory Tip:</strong> red tape（官僚程序）来自旧时用红带捆公文——&quot;带子&quot;的比喻义。tape 作动词时既可&quot;录&quot;也可&quot;贴&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数表材料：a piece of tape。</li><li>动词&quot;录制&quot;过去式 taped，不双写。</li><li>red tape 是贬义&quot;官僚程序&quot;，不要按字面理解。</li></ul></div><div class="vocab-card"><h2 id="binary" tabindex="-1"><a class="header-anchor" href="#binary"><span>Binary</span></a></h2><p class="vc-meta"><strong>/ˈbaɪnəri/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：二进制的；二元的，由两部分组成的</li><li>名词：二进制（系统）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>binary code</td><td>二进制代码</td></tr><tr><td>the binary system</td><td>二进制系统</td></tr><tr><td>binary digits</td><td>二进制位</td></tr><tr><td>a binary choice</td><td>二选一的选择</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how text is converted into binary code.</p><blockquote><p>该示意图显示了文字如何转换为二进制代码。</p></blockquote><p><strong>Writing Task 2</strong> Framing every issue as a binary choice makes compromise impossible.</p><blockquote><p>把每个议题都框成二选一，妥协就不可能了。</p></blockquote><p><strong>Speaking</strong> Computers only understand binary — everything else is translation.</p><blockquote><p>计算机只懂二进制，其他都是翻译。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dual</td><td>双重的</td><td>指两个部分并存，非数制</td></tr><tr><td>two-state</td><td>双态的</td><td>技术描述，指两种状态</td></tr><tr><td>base-2</td><td>二进制的</td><td>数学表述，写作少用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>binarius</em> ← <em>bini</em>（两个一组）</li><li><strong>Family:</strong> binary 二进制的 / bin 箱子（同源&quot;双格&quot;）/ combine 结合 / biscuit（同源&quot;两次烤&quot;）</li><li><strong>Memory Tip:</strong> bi- 是&quot;二&quot;：binary（二进制）、bicycle（两轮）、bilingual（双语）。二进制只有 0 和 1 两个&quot;状态&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>binary 是形容词，说&quot;二进制&quot;可加 the binary system。</li><li>比喻义 a binary choice（非此即彼的选择）在议论文里很好用。</li><li>拼写 bi-nary，重音在第一音节。</li></ul></div><div class="vocab-card"><h2 id="digital" tabindex="-1"><a class="header-anchor" href="#digital"><span>Digital</span></a></h2><p class="vc-meta"><strong>/ˈdɪdʒɪtl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>数字的，数码的（以数字信号表示）</li><li>手指的（解剖，罕见）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>digital technology</td><td>数字技术</td></tr><tr><td>the digital economy</td><td>数字经济</td></tr><tr><td>digital divide</td><td>数字鸿沟</td></tr><tr><td>digital native</td><td>数字原住民</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the shift from analogue to digital subscriptions.</p><blockquote><p>该图表显示了从模拟到数字订阅的转变。</p></blockquote><p><strong>Writing Task 2</strong> The digital divide is less about devices than about confidence.</p><blockquote><p>数字鸿沟的关键不在设备，而在信心。</p></blockquote><p><strong>Speaking</strong> I still prefer paper maps to digital ones when I&#39;m hiking.</p><blockquote><p>徒步时我还是更喜欢纸质地图。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>electronic</td><td>电子的</td><td>范围更广，含模拟电路</td></tr><tr><td>online</td><td>在线的</td><td>强调联网，非编码方式</td></tr><tr><td>computerised</td><td>计算机化的</td><td>强调由计算机管理</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>digitus</em>（手指）→ 手指计数 → 数字</li><li><strong>Family:</strong> digital 数字的 / digit 数字；手指 / digitally 数字化地 / digitise 数字化</li><li><strong>Memory Tip:</strong> digit 既是&quot;手指&quot;也是&quot;数字&quot;——因为古人用手指计数。所以 digital 的底层画面是&quot;用手指点着数&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 electronic 不同：digital 强调用离散数字表示，electronic 只说明用电。</li><li>digital divide（数字鸿沟）是固定搭配，冠词用 the。</li><li>拼写 dig-ital，别写成 <s>digitial</s>。</li></ul></div><div class="vocab-card"><h2 id="wireless" tabindex="-1"><a class="header-anchor" href="#wireless"><span>Wireless</span></a></h2><p class="vc-meta"><strong>/ˈwaɪələs/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：无线的（不用导线传输）</li><li>名词（旧）：无线电收音机</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>wireless network</td><td>无线网络</td></tr><tr><td>wireless charging</td><td>无线充电</td></tr><tr><td>a wireless connection</td><td>无线连接</td></tr><tr><td>wireless technology</td><td>无线技术</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the coverage of the campus wireless network.</p><blockquote><p>该地图显示了校园无线网络的覆盖范围。</p></blockquote><p><strong>Writing Task 2</strong> Wireless charging sounds convenient but wastes more energy than a cable.</p><blockquote><p>无线充电听着方便，却比线充更费电。</p></blockquote><p><strong>Speaking</strong> The wireless keeps dropping in the back bedroom.</p><blockquote><p>后面卧室的无线网总断。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cordless</td><td>无绳的</td><td>多用于家电，如无绳电话</td></tr><tr><td>cable-free</td><td>无线的</td><td>描述性说法，少见</td></tr><tr><td>Wi-Fi</td><td>无线局域网</td><td>具体标准，不能泛指所有无线</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>wire</em>（金属线）+ <em>-less</em>（无）</li><li><strong>Family:</strong> wireless 无线的 / wire 电线 / wired 有线的；联网的 / wiring 线路</li><li><strong>Memory Tip:</strong> -less 表示&quot;没有&quot;：wireless（无线）、cordless（无绳）、paperless（无纸）。wired 则是它的反义：a wired connection。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>wireless 是形容词，说&quot;无线网络&quot;用 wireless network，不加 <s>the</s> 泛指时。</li><li>Wi-Fi 只是无线技术的一种，不能与 wireless 完全等同。</li><li>拼写 wire-less，中间不加连字符。</li></ul></div><div class="vocab-card"><h2 id="high-definition" tabindex="-1"><a class="header-anchor" href="#high-definition"><span>High-definition</span></a></h2><p class="vc-meta"><strong>/ˌhaɪ defɪˈnɪʃn/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>高清晰度的（图像、视频）</li><li>（名词）高清晰度</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>high-definition video</td><td>高清视频</td></tr><tr><td>high-definition images</td><td>高清图像</td></tr><tr><td>in high definition</td><td>以高清格式</td></tr><tr><td>HD</td><td>高清（缩写）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the file size of standard and high-definition footage.</p><blockquote><p>该图表比较了标清与高清素材的文件大小。</p></blockquote><p><strong>Writing Task 2</strong> High-definition cameras let anyone record evidence that once required a news crew.</p><blockquote><p>高清摄像机让任何人都能记录下过去需要新闻摄制组才能拍到的证据。</p></blockquote><p><strong>Speaking</strong> The match looks completely different in high definition.</p><blockquote><p>这场比赛在高清下看着完全不一样。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>HD</td><td>高清</td><td>缩写，口语与商品名常用</td></tr><tr><td>high-resolution</td><td>高分辨率</td><td>指像素密度，技术表述</td></tr><tr><td>sharp</td><td>清晰的</td><td>主观描述，非技术标准</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>high</em>（高）+ <em>definition</em>（清晰度，本义&quot;界定&quot;）</li><li><strong>Family:</strong> high-definition 高清 / definition 定义；清晰度 / define 界定 / definite 明确的</li><li><strong>Memory Tip:</strong> definition 除了&quot;定义&quot;，还指&quot;（成像的）清晰度&quot;——边界被&quot;界定&quot;得清楚。所以高清就是 high definition。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式常带连字符 high-definition，缩写统一写 HD。</li><li>说&quot;以高清&quot;用 in high definition。</li><li>别把 definition 只理解成&quot;定义&quot;，这里是&quot;清晰度&quot;。</li></ul></div><div class="vocab-card"><h2 id="audio" tabindex="-1"><a class="header-anchor" href="#audio"><span>Audio</span></a></h2><p class="vc-meta"><strong>/ˈɔːdiəʊ/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：音频的，声音的</li><li>名词：声音信号，音频（不可数）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>audio quality</td><td>音质</td></tr><tr><td>audio recording</td><td>录音</td></tr><tr><td>audio input</td><td>音频输入</td></tr><tr><td>audio-visual</td><td>视听的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows the audio signal passing through the amplifier.</p><blockquote><p>该示意图显示了音频信号通过放大器的过程。</p></blockquote><p><strong>Writing Task 2</strong> Audio recordings of lectures are useful only if students actually revisit them.</p><blockquote><p>讲座录音只有在学生真的回听时才有用。</p></blockquote><p><strong>Speaking</strong> The audio&#39;s fine but the video keeps freezing.</p><blockquote><p>声音没问题，画面老卡。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sound</td><td>声音</td><td>日常词，不限于录制信号</td></tr><tr><td>acoustic</td><td>声学的</td><td>指物理声波与空间效果</td></tr><tr><td>sonic</td><td>声音的</td><td>多用于&quot;声速、声波&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>audire</em>（听）</li><li><strong>Family:</strong> audio 音频 / audible 听得见的 / audience 听众 / audition 试音；试镜</li><li><strong>Memory Tip:</strong> aud = 听：audible（听得见）、audience（听的人→观众）、auditorium（听的地方→礼堂）。audio 就是&quot;听的那一路&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>an audio</s> ✘；说 an audio file。</li><li>拼写 au-dio，别写成 <s>adio</s>。</li><li>与 video 成对使用：audio and video，写作里避免混用 sound。</li></ul></div><div class="vocab-card"><h2 id="vision" tabindex="-1"><a class="header-anchor" href="#vision"><span>Vision</span></a></h2><p class="vc-meta"><strong>/ˈvɪʒn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>视力，视觉</li><li>远见，愿景；（图像）视觉呈现</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a clear vision of</td><td>对……的清晰愿景</td></tr><tr><td>20/20 vision</td><td>正常视力（美式表述）</td></tr><tr><td>computer vision</td><td>计算机视觉</td></tr><tr><td>a man of vision</td><td>有远见的人</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the growth of the computer vision market since 2018.</p><blockquote><p>该图表显示了 2018 年以来计算机视觉市场的增长。</p></blockquote><p><strong>Writing Task 2</strong> A city without a vision for transport simply builds more roads.</p><blockquote><p>没有交通愿景的城市只会修更多的路。</p></blockquote><p><strong>Speaking</strong> My night vision is terrible — I can&#39;t drive after dark.</p><blockquote><p>我夜视很差，天黑就不敢开车。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>eyesight</td><td>视力</td><td>只指生理视觉</td></tr><tr><td>foresight</td><td>远见</td><td>只指预见能力</td></tr><tr><td>dream</td><td>梦想</td><td>口语，情感色彩强</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>visio</em> ← <em>videre</em>（看）</li><li><strong>Family:</strong> vision 视觉；愿景 / visible 可见的 / visual 视觉的 / video 视频 / supervise 监督（从上方看）</li><li><strong>Memory Tip:</strong> vid/vis = 看：visible、visual、video、supervise（super + vid = 从上面看→监督）。vision 一身两职：眼睛的&quot;看&quot;，和心里的&quot;看见&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>表&quot;视力&quot;不可数：have poor vision。</li><li>表&quot;愿景&quot;可数：a vision for the future。</li><li>拼写 vi-sion，注意 s 读 /ʒ/。</li></ul></div><div class="vocab-card"><h2 id="fantasy" tabindex="-1"><a class="header-anchor" href="#fantasy"><span>Fantasy</span></a></h2><p class="vc-meta"><strong>/ˈfæntəsi/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>幻想，想象；幻想作品（奇幻文学）</li><li>空想，不切实际的念头</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>live in a fantasy world</td><td>活在幻想中</td></tr><tr><td>fantasy fiction</td><td>奇幻小说</td></tr><tr><td>a childhood fantasy</td><td>童年幻想</td></tr><tr><td>indulge in fantasy</td><td>沉溺于幻想</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares sales of fantasy and science fiction over ten years.</p><blockquote><p>该图表比较了十年间奇幻与科幻作品的销量。</p></blockquote><p><strong>Writing Task 2</strong> Escapist fantasy is not the opposite of serious thought; it is often its starting point.</p><blockquote><p>逃避式幻想并非严肃思考的对立面，它常常是后者的起点。</p></blockquote><p><strong>Speaking</strong> As a kid I had a fantasy about living on a boat.</p><blockquote><p>小时候我幻想过住在船上。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>imagination</td><td>想象力</td><td>中性，指能力</td></tr><tr><td>daydream</td><td>白日梦</td><td>口语，指走神时的遐想</td></tr><tr><td>illusion</td><td>错觉</td><td>指错误认知，非主动想象</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>phantasia</em>（显现、形象）← <em>phainein</em>（显示）</li><li><strong>Family:</strong> fantasy 幻想 / fantastic 极好的；奇异的 / phantom 幽灵 / phenomenon 现象（同源&quot;显现&quot;）</li><li><strong>Memory Tip:</strong> phan = 显现，fantasy 是&quot;让不存在的东西在脑中显现&quot;。fantastic 现在多说&quot;极好的&quot;，本义是&quot;像幻想一样的&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a fantasy / fantasies。</li><li>fantasy 与 science fiction 是两个类型，别混称。</li><li>拼写 fan-tasy，注意中间是 t 不是 <s>ph</s>（<s>phantasy</s> 是古旧拼法）。</li></ul></div><div class="vocab-card"><h2 id="science-fiction" tabindex="-1"><a class="header-anchor" href="#science-fiction"><span>Science fiction</span></a></h2><p class="vc-meta"><strong>/ˌsaɪəns ˈfɪkʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>科幻小说，科幻作品（常缩写 SF 或 sci-fi）</li><li>科幻类型</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a science fiction novel</td><td>一本科幻小说</td></tr><tr><td>science fiction film</td><td>科幻电影</td></tr><tr><td>science fiction writer</td><td>科幻作家</td></tr><tr><td>sci-fi</td><td>科幻（口语缩写）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the box-office share of science fiction films since 2000.</p><blockquote><p>该图表显示了 2000 年以来科幻电影的票房占比。</p></blockquote><p><strong>Writing Task 2</strong> Science fiction is useful precisely because it exaggerates the present rather than predicting the future.</p><blockquote><p>科幻之所以有用，恰恰因为它夸张当下，而非预测未来。</p></blockquote><p><strong>Speaking</strong> I grew up on science fiction — my father had shelves of it.</p><blockquote><p>我是看科幻长大的，我爸有好几书架。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sci-fi</td><td>科幻</td><td>口语缩写，正式写作少用</td></tr><tr><td>speculative fiction</td><td>推想小说</td><td>更学术，涵盖范围更广</td></tr><tr><td>futuristic fiction</td><td>未来小说</td><td>强调未来设定，非类型名</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>scientia</em>（知识）+ <em>fictio</em>（塑造）← <em>fingere</em>（捏塑）</li><li><strong>Family:</strong> science fiction 科幻 / fiction 小说（虚构）/ fictional 虚构的 / nonfiction 非虚构</li><li><strong>Memory Tip:</strong> fiction 与&quot;捏塑&quot;同源——捏出来的故事。science fiction 就是&quot;用科学捏出来的故事&quot;。缩写 SF 比 sci-fi 更正式。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数，说 a science fiction novel，不说 <s>a science fiction</s>。</li><li>缩写 sci-fi 带连字符，正式文章用全称。</li><li>与 fantasy 区分：科幻有科学设定，奇幻多涉魔法。</li></ul></div>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};